1872	int ParameterManager::LoadDocument(const XERCES_CPP_NAMESPACE_QUALIFIER InputSource& inputSource)
1873	{
1874	    //
1875	    //  Create our parser, then attach an error handler to the parser.
1876	    //  The parser will call back to methods of the ErrorHandler if it
1877	    //  discovers errors during the course of parsing the XML document.
1878	    //
1879	    auto parser = std::make_unique<XercesDOMParser>();
1880	    auto entityBlocker = std::make_unique<NoOpEntityResolver>();
1881	    parser->setValidationScheme(gValScheme);
1882	    parser->setDoNamespaces(gDoNamespaces);
1883	    parser->setDoSchema(gDoSchema);
1884	    parser->setValidationSchemaFullChecking(gSchemaFullChecking);
1885	    parser->setCreateEntityReferenceNodes(gDoCreate);
1886	    parser->setDisableDefaultEntityResolution(true);
1887	    parser->setEntityResolver(entityBlocker.get());
1888	
1889	    auto errReporter = std::make_unique<DOMTreeErrorReporter>();
1890	    parser->setErrorHandler(errReporter.get());
1891	
1892	    //
1893	    //  Parse the XML file, catching any XML exceptions that might propagate
1894	    //  out of it.
1895	    //
1896	    bool errorsOccurred = false;
1897	    try {
1898	        parser->parse(inputSource);
1899	    }
1900	    catch (const XMLException& e) {
1901	        std::cerr << "An error occurred during parsing\n   Message: " << StrX(e.getMessage())
1902	                  << "\n";
1903	        errorsOccurred = true;
1904	    }
1905	    catch (const DOMException& e) {
1906	        std::cerr << "A DOM error occurred during parsing\n   DOMException code: " << e.code
1907	                  << "\n";
1908	        errorsOccurred = true;
1909	    }
1910	    catch (...) {
1911	        std::cerr << "An error occurred during parsing\n " << "\n";
1912	        errorsOccurred = true;
1913	    }
1914	
1915	    if (errorsOccurred) {
1916	        return 0;
1917	    }
1918	
1919	    _pDocument = parser->adoptDocument();
1920	
1921	    if (!_pDocument) {
1922	        throw XMLBaseException("Malformed Parameter document: Invalid document");
1923	    }
1924	
1925	    DOMElement* rootElem = _pDocument->getDocumentElement();
1926	    if (!rootElem) {
1927	        throw XMLBaseException("Malformed Parameter document: Root group not found");
1928	    }
1929	
1930	    _pGroupNode = FindElement(rootElem, "FCParamGroup", "Root");
1931	
1932	    if (!_pGroupNode) {
1933	        throw XMLBaseException("Malformed Parameter document: Root group not found");
1934	    }
1935	
1936	    return 1;
1937	}
